from pathlib import Path
import json, subprocess, re
root=Path(__file__).resolve().parent.parent
out=root/'out'
items=[]
def src(file,anchor,count=7,before=0):
    lines=(root/file).read_text(encoding='utf-8').splitlines()
    hits=[i for i,s in enumerate(lines) if anchor in s]
    if not hits: raise ValueError((file,anchor))
    start=max(0,hits[0]-before)
    return {'file':file,'line':start+1,'quote':'\n'.join(f'{i+1}: {lines[i]}' for i in range(start,min(start+count,len(lines))))}
def add(id,severity,branches,title,evidence,why,scenario,fix,confidence='High',proof=''):
    items.append(dict(id=id,severity=severity,branches=branches,title=title,evidence=evidence,why=why,failure_scenario=scenario,fix=fix,confidence=confidence,proof=proof))
